mapper.select:
SELECT T.CUSTNO, C.INVTP, C.INVTP AS INVTP_NAME, C.INVNM, R.FUNDACCT, L.EVALDATE, CASE WHEN UB.ECCUSTNO IS NOT NULL THEN '网上' ELSE '网下' END AS REGIONCODE_NAME, CASE WHEN C.SPECRISKLEVEL = '1' THEN '0 C0-最低' ELSE CONCAT(CONCAT(L.RISKLEVEL,' '),IBF_GET_PARAMNAME('SYSTEM','CUSTRISKLEVEL',L.RISKLEVEl)) END AS RISKLEVEL_NAME, CASE WHEN NVL(DC.INVPRTP, UB.INVPRTP) = '0' THEN '' ELSE IBF_GET_PARAMNAME('SYSTEM','OLD_RISKLEVEL',L.OLD_RISKLEVEl) END AS OLD_RISKLEVEL_NAME, L.RISKLEVEL, L.EVALTIME, L.EVALTYPE, (CONCAT((TO_CHAR(TO_NUMBER(SUBSTR(L.EVALDATE,0,4)) + 1)),SUBSTR(L.EVALDATE,5))) OUTDATE,
(SELECT EMNAME AS OPNM FROM T_ECC_EMPLOYEE WHERE TRIM(EMPID) = L.TERMINALINFO) OPNM, L.TERMINALINFO, UB.ECCUSTNO, CE.VOICERECORD, UA.APPTP, UA.APPTP AS APPTP_NAME, UA.APDT, CASE WHEN UB.INVPRTP = '0' AND UB.INVPRTPSCORE >= 60 THEN '' WHEN (SELECT COUNT(1) FROM USER_APPCVSITP T WHERE T.CUSTNO = UB.ECCUSTNO) > 0 THEN (SELECT APPST FROM USER_APPCVSITP UA WHERE UA.CUSTNO = UB.ECCUSTNO) ELSE '' END AS APPST, CASE WHEN UB.INVPRTP = '0' AND UB.INVPRTPSCORE >= 60 THEN '' WHEN (SELECT COUNT(1) FROM USER_APPCVSITP T WHERE T.CUSTNO = UB.ECCUSTNO) > 0 THEN (SELECT APPST FROM USER_APPCVSITP UA WHERE UA.CUSTNO = UB.ECCUSTNO) ELSE '' END AS APPST_NAME, UA.CHKFLAG, NVL(DC.INVPRTP, UB.INVPRTP) INVPRTP, NVL(DC.INVPRTP, UB.INVPRTP) INVPRTP_NAME, L.EVALANSWER, L.OLD_RISKLEVEl, C.SPECRISKLEVEL FROM (SELECT DISTINCT (CUSTNO) FROM TRADEACCOINFO TT) T, (SELECT FUNDACCT, CUSTNO FROM TRADEACCORELA WHERE FUNDACCT IS NOT NULL GROUP BY FUNDACCT, CUSTNO) R, (SELECT BAS.CMFUSERID, BAS.INVPRTP, BAS.INVPRTPSCORE, A.ECCUSTNO FROM USER_BASEINFO BAS, USER_ACCORLA A WHERE A.CMFUSERID(+) = BAS.CMFUSERID) UB, USER_APPCVSITP UA, CUSTINFO C, CUSTRISKLEVEL L, CUSTINFOEX CE, DS_CUSTCLASSINFO DC WHERE T.CUSTNO = R.CUSTNO(+) AND T.CUSTNO = C.CUSTNO AND T.CUSTNO = L.CUSTNO(+) AND T.CUSTNO = UA.CUSTNO(+) AND CE.CUSTNO = T.CUSTNO AND T.CUSTNO = DC.CUSTNO(+) AND T.CUSTNO = UB.ECCUSTNO(+)
AND C.INVNM LIKE '%'||#{sp.invnm}||'%'
AND C.INVTP = #{sp.invtp}
AND C.CUSTNO = #{sp.custno}
AND L.RISKLEVEL IS NULL
AND L.RISKLEVEL = #{sp.risklevel} AND C.SPECRISKLEVEL <> '1'
AND R.FUNDACCT LIKE '%'||#{sp.fundacct}||'%'
AND DC.INVPRTP = #{sp.invprtp}
AND C.SPECRISKLEVEL = '1'
AND L.EVALDATE >= #{sp.beginDate}
AND L.EVALDATE <= #{sp.endDate}
ORDER BY OUTDATE ASC

SELECT T.CUSTNO, C.INVTP, C.INVTP AS INVTP_NAME, C.INVNM, R.FUNDACCT, L.EVALDATE, CASE WHEN UB.ECCUSTNO IS NOT NULL THEN '网上' ELSE '网下' END AS REGIONCODE_NAME, CASE WHEN C.SPECRISKLEVEL = '1' THEN '0 C0-最低' ELSE CONCAT(CONCAT(L.RISKLEVEL,' '),DECODE(L.RISKLEVEL,'0','C0-最低',IBF_GET_PARAMNAME('SYSTEM','CUSTRISKLEVEL',L.RISKLEVEl))) END AS RISKLEVEL_NAME, CASE WHEN NVL(DC.INVPRTP, UB.INVPRTP) = '0' THEN '' ELSE IBF_GET_PARAMNAME('SYSTEM','OLD_RISKLEVEL',L.OLD_RISKLEVEl) END AS OLD_RISKLEVEL_NAME, L.RISKLEVEL, L.EVALTIME, L.EVALTYPE, (SELECT CONCAT((TO_CHAR(TO_NUMBER(SUBSTR(L.EVALDATE,0,4)) + 1)),SUBSTR(L.EVALDATE,5)) FROM DUAL) OUTDATE, (SELECT EMNAME AS OPNM FROM T_ECC_EMPLOYEE WHERE TRIM(EMPID) = L.TERMINALINFO) OPNM, L.TERMINALINFO, UB.ECCUSTNO, CE.VOICERECORD, UA.APPTP, UA.APPTP AS APPTP_NAME, UA.APDT, CASE WHEN UB.INVPRTP = '0' AND UB.INVPRTPSCORE >= 60 THEN '' WHEN (SELECT COUNT(1) FROM USER_APPCVSITP T WHERE T.CUSTNO = UB.ECCUSTNO) > 0 THEN (SELECT APPST FROM USER_APPCVSITP UA WHERE UA.CUSTNO = UB.ECCUSTNO) ELSE '' END AS APPST, CASE WHEN UB.INVPRTP = '0' AND UB.INVPRTPSCORE >= 60 THEN '' WHEN (SELECT COUNT(1) FROM USER_APPCVSITP T WHERE T.CUSTNO = UB.ECCUSTNO) > 0 THEN (SELECT APPST FROM USER_APPCVSITP UA WHERE UA.CUSTNO = UB.ECCUSTNO) ELSE '' END AS APPST_NAME, UA.CHKFLAG, NVL(DC.INVPRTP, UB.INVPRTP) INVPRTP, NVL(DC.INVPRTP, UB.INVPRTP) INVPRTP_NAME, L.EVALANSWER, L.OLD_RISKLEVEl, C.SPECRISKLEVEL FROM (SELECT DISTINCT (CUSTNO) FROM TRADEACCOINFO TT) T, (SELECT FUNDACCT, CUSTNO FROM TRADEACCORELA WHERE FUNDACCT IS NOT NULL GROUP BY FUNDACCT, CUSTNO) R, (SELECT BAS.CMFUSERID, BAS.INVPRTP, BAS.INVPRTPSCORE, A.ECCUSTNO FROM USER_BASEINFO BAS, USER_ACCORLA A WHERE A.CMFUSERID(+) = BAS.CMFUSERID) UB, USER_APPCVSITP UA, CUSTINFO C, CUSTRISKLEVEL L, CUSTINFOEX CE, DS_CUSTCLASSINFO DC WHERE T.CUSTNO = R.CUSTNO(+) AND T.CUSTNO = C.CUSTNO AND T.CUSTNO = L.CUSTNO(+) AND T.CUSTNO = UA.CUSTNO(+) AND CE.CUSTNO = T.CUSTNO AND T.CUSTNO = DC.CUSTNO(+) AND T.CUSTNO = UB.ECCUSTNO(+)
AND C.INVNM LIKE '%'||#{sp.invnm}||'%'
AND C.INVTP = #{sp.invtp}
AND C.CUSTNO = #{sp.custno}
AND L.RISKLEVEL IS NULL
AND L.RISKLEVEL = #{sp.risklevel} AND C.SPECRISKLEVEL <> '1'
AND R.FUNDACCT LIKE '%'||#{sp.fundacct}||'%'
AND DC.INVPRTP = #{sp.invprtp}
AND C.SPECRISKLEVEL = '1'
AND L.EVALDATE >= #{sp.beginDate}
AND L.EVALDATE <= #{sp.endDate}
ORDER BY OUTDATE ASC

SELECT COUNT(*) FROM (SELECT DISTINCT (CUSTNO) FROM TRADEACCOINFO TT) T, (SELECT FUNDACCT, CUSTNO FROM TRADEACCORELA WHERE FUNDACCT IS NOT NULL GROUP BY FUNDACCT, CUSTNO) R, (SELECT BAS.CMFUSERID, BAS.INVPRTP, BAS.INVPRTPSCORE, A.ECCUSTNO FROM USER_BASEINFO BAS, USER_ACCORLA A WHERE A.CMFUSERID(+) = BAS.CMFUSERID) UB, USER_APPCVSITP UA, CUSTINFO C, CUSTRISKLEVEL L, CUSTINFOEX CE, DS_CUSTCLASSINFO DC WHERE T.CUSTNO = R.CUSTNO(+) AND T.CUSTNO = C.CUSTNO AND T.CUSTNO = L.CUSTNO(+) AND T.CUSTNO = UA.CUSTNO(+) AND CE.CUSTNO = T.CUSTNO AND T.CUSTNO = DC.CUSTNO(+) AND T.CUSTNO = UB.ECCUSTNO(+)
AND C.INVNM LIKE '%'||#{sp.invnm}||'%'
AND C.INVTP = #{sp.invtp}
AND C.CUSTNO = #{sp.custno}
AND L.RISKLEVEL IS NULL
AND L.RISKLEVEL = #{sp.risklevel} AND C.SPECRISKLEVEL <> '1'
AND R.FUNDACCT LIKE '%'||#{sp.fundacct}||'%'
AND DC.INVPRTP = #{sp.invprtp}
AND C.SPECRISKLEVEL = '1'
AND L.EVALDATE >= #{sp.beginDate}
AND L.EVALDATE <= #{sp.endDate}
